class LoggingFilter @Inject() (implicit ec: ExecutionContext) extends Filter {
  def apply(next: RequestHeader => Future[Result])(req: RequestHeader): Future[Result] = {
    val t0 = System.currentTimeMillis
    next(req).map { result =>                       // downstream chain
      val ms = System.currentTimeMillis - t0
      logger.info(s"${req.method} ${req.uri} took ${ms}ms")
      result.withHeaders("Request-Time" -> ms.toString)
    }
  }
}
